INSERT INTO alembic_version (version_num) VALUES ('0001_initial') RETURNING alembic_version.version_num;
INSERT INTO job_roles (title, description, required_skills) VALUES ('Software Developer', 'Build and maintain backend services and web applications using Python/Java, REST APIs, databases, Git and cloud deployment.', '["python", "java", "sql", "git", "rest api", "data structures", "algorithms", "docker", "oop", "testing"]'::jsonb);
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES ((SELECT id FROM job_roles WHERE title = 'Software Developer'), 0, 'Explain the difference between a process and a thread.', 'A process is an independent program in execution with its own memory space, while a thread is a lightweight unit of execution inside a process that shares the process memory. Threads are cheaper to create and switch, and communicate through shared memory, but need synchronization like locks to avoid race conditions. Processes are isolated, so a crash in one does not affect others, and they communicate through inter-process communication.', '["memory", "shared", "independent", "lightweight", "context switch", "synchronization", "race condition", "isolation"]'::jsonb, 'technical', 120, 'technical', NULL, NULL, NULL, NULL, NULL, 0, 'seed');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES ((SELECT id FROM job_roles WHERE title = 'Software Developer'), 1, 'What is a REST API and what makes an API RESTful?', 'REST is an architectural style where resources are identified by URLs and manipulated with standard HTTP methods like GET, POST, PUT and DELETE. A RESTful API is stateless, uses a client-server model, returns representations such as JSON, uses proper status codes, and supports caching and a uniform interface.', '["resource", "http", "get", "post", "stateless", "json", "status code", "client server"]'::jsonb, 'technical', 120, 'technical', NULL, NULL, NULL, NULL, NULL, 0, 'seed');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES ((SELECT id FROM job_roles WHERE title = 'Software Developer'), 2, 'How would you find and fix a slow database query in production?', 'First measure using slow query logs or APM to find the query, then run EXPLAIN ANALYZE to inspect the execution plan. Look for full table scans and add suitable indexes, avoid SELECT *, fix N+1 queries, paginate results and consider caching. Test the change on staging, deploy, and monitor the latency afterwards.', '["explain", "index", "execution plan", "n+1", "cache", "monitor", "full table scan", "logs"]'::jsonb, 'technical', 120, 'technical', NULL, NULL, NULL, NULL, NULL, 0, 'seed');
INSERT INTO job_roles (title, description, required_skills) VALUES ('Data Analyst', 'Clean, analyse and visualise business data using SQL, Excel, Python (pandas) and BI tools like Power BI or Tableau; communicate insights to stakeholders.', '["sql", "excel", "python", "pandas", "power bi", "tableau", "statistics", "data visualization", "data cleaning"]'::jsonb);
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES ((SELECT id FROM job_roles WHERE title = 'Data Analyst'), 0, 'How do you handle missing values in a dataset?', 'First understand why data is missing and how much is missing per column. Then choose a strategy: drop rows or columns when the missing share is small or the column is not useful, impute with mean, median or mode, use forward fill for time series, or model-based imputation. Optionally add an indicator flag and always validate the impact on the analysis.', '["drop", "impute", "mean", "median", "mode", "forward fill", "percentage", "bias"]'::jsonb, 'technical', 120, 'technical', NULL, NULL, NULL, NULL, NULL, 0, 'seed');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES ((SELECT id FROM job_roles WHERE title = 'Data Analyst'), 1, 'Explain the difference between INNER JOIN, LEFT JOIN and FULL OUTER JOIN.', 'An INNER JOIN returns only rows with matching keys in both tables. A LEFT JOIN returns all rows from the left table and matching rows from the right table, with NULLs where there is no match. A FULL OUTER JOIN returns all rows from both tables, filling NULLs on whichever side has no match.', '["matching", "both tables", "left table", "null", "all rows", "key"]'::jsonb, 'technical', 120, 'technical', NULL, NULL, NULL, NULL, NULL, 0, 'seed');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES ((SELECT id FROM job_roles WHERE title = 'Data Analyst'), 2, 'Tell me how you would present a data insight to a non-technical manager.', 'Start with the business question and the key takeaway, use one simple, clean visual, avoid jargon, quantify the impact in business terms like revenue or cost, give a clear recommendation and next steps, and be ready with supporting detail if asked.', '["business", "visual", "simple", "impact", "recommendation", "story", "jargon"]'::jsonb, 'technical', 120, 'technical', NULL, NULL, NULL, NULL, NULL, 0, 'seed');
INSERT INTO job_roles (title, description, required_skills) VALUES ('IT Executive', 'Manage IT infrastructure, networks, user support, security and vendor coordination for the organisation.', '["networking", "windows server", "active directory", "troubleshooting", "security", "backup", "linux", "itil", "firewall"]'::jsonb);
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES ((SELECT id FROM job_roles WHERE title = 'IT Executive'), 0, 'Explain how you would handle a sudden network outage affecting multiple departments.', 'Identify the scope and root cause by checking monitoring, switches, routers, firewall and server logs. Communicate the outage and expected timelines to the affected departments, apply a workaround or failover to restore service quickly, fix the root cause, then document the incident and preventive measures in a post-incident review.', '["root cause", "logs", "switch", "communicate", "failover", "document", "monitoring", "escalate"]'::jsonb, 'technical', 120, 'technical', NULL, NULL, NULL, NULL, NULL, 0, 'seed');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES ((SELECT id FROM job_roles WHERE title = 'IT Executive'), 1, 'How do you ensure company data is backed up and recoverable?', 'Follow the 3-2-1 rule: three copies of data, on two different media, one offsite or in the cloud. Automate scheduled full and incremental backups, encrypt them, monitor backup jobs, and regularly test restores against defined RPO and RTO targets.', '["3-2-1", "offsite", "cloud", "incremental", "encrypt", "test restore", "rpo", "rto", "schedule"]'::jsonb, 'technical', 120, 'technical', NULL, NULL, NULL, NULL, NULL, 0, 'seed');
INSERT INTO job_roles (title, description, required_skills) VALUES ('Machine Learning Engineer', 'Design, train, evaluate and deploy machine learning models; build data pipelines and MLOps workflows.', '["python", "machine learning", "deep learning", "pytorch", "tensorflow", "scikit-learn", "sql", "mlops", "docker", "statistics", "nlp"]'::jsonb);
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES ((SELECT id FROM job_roles WHERE title = 'Machine Learning Engineer'), 0, 'What is overfitting and how do you prevent it?', 'Overfitting is when a model learns noise in the training data and performs well on training but poorly on unseen data. Detect it with a validation set or cross-validation. Prevent it with more data, data augmentation, regularization such as L1, L2 or dropout, simpler models, early stopping and feature selection.', '["training", "validation", "generalize", "cross validation", "regularization", "dropout", "early stopping", "more data"]'::jsonb, 'technical', 120, 'technical', NULL, NULL, NULL, NULL, NULL, 0, 'seed');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES ((SELECT id FROM job_roles WHERE title = 'Machine Learning Engineer'), 1, 'How would you deploy and monitor a machine learning model in production?', 'Package the model with its preprocessing into a versioned artifact, serve it behind an API such as FastAPI in a Docker container, and deploy with CI/CD. Monitor latency, errors, input data drift and prediction drift, log predictions, and retrain or roll back based on alerts.', '["api", "docker", "version", "ci/cd", "monitor", "drift", "latency", "retrain", "rollback"]'::jsonb, 'technical', 120, 'technical', NULL, NULL, NULL, NULL, NULL, 0, 'seed');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Tell me about yourself.', 'A short structured introduction: name, current course and year, key technical skills, one or two projects or internships with what the candidate built or achieved, strengths or interests, and a career goal that connects to the role.', '["course", "skills", "project", "goal", "interest", "learn"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'intro', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Introduce yourself and tell me why you chose your course.', 'Brief introduction (name, course, year), a genuine reason for choosing the course such as interest in technology or problem solving, what the candidate has learned or built so far, and how it connects to future career goals.', '["course", "interest", "technology", "learn", "project", "career"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'intro', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Walk me through your background and what you are good at.', 'A structured summary of education and current course, strongest technical and soft skills backed by an example or project, achievements or certifications, and what the candidate wants to do next.', '["education", "skills", "example", "project", "strength", "achievement"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'intro', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Give me a two-minute introduction about yourself and your goals.', 'Concise self introduction with course and year, key skills, a highlight project or activity, personal strengths, and clear short-term and long-term career goals.', '["skills", "project", "strength", "short term", "long term", "goal"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'intro', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Describe a time you worked in a team. What was your role?', 'STAR answer: the situation and team project, the candidate''s specific role and responsibilities, actions taken to coordinate, communicate and help others, the result or outcome, and what was learned about teamwork.', '["team", "role", "responsibility", "communicate", "result", "learned"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'teamwork', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'How do you handle pressure or tight deadlines?', 'Explains a method such as prioritising tasks, breaking work into smaller parts, planning time and staying calm, supported by a real example of meeting a deadline, and the result.', '["prioritize", "plan", "deadline", "calm", "example", "result"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'pressure', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What are your strengths and weaknesses?', 'Names one or two relevant strengths with a proof example, and one genuine weakness that is not critical to the job, along with concrete steps being taken to improve it.', '["strength", "example", "weakness", "improve", "working on"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'strengths', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Tell me about a disagreement with a teammate and how you resolved it.', 'STAR answer: describes the disagreement respectfully, listening to the other view, discussing calmly, finding common ground or a compromise based on facts or the project goal, the outcome, and the lesson learned.', '["listen", "discuss", "understand", "compromise", "solution", "outcome"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'conflict', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Tell me about a mistake or failure and what you learned from it.', 'Honestly describes a real mistake, takes ownership, explains what was done to fix it, and the specific lesson learned and how behaviour changed afterwards.', '["mistake", "responsibility", "fixed", "learned", "improve", "now"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'failure', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Describe a situation where you showed leadership.', 'STAR answer: a situation where the candidate took initiative or led a group, how tasks were planned and divided, how others were motivated or supported, the measurable result, and the learning.', '["initiative", "lead", "plan", "motivate", "team", "result"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'leadership', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'How do you learn a new technology quickly?', 'Describes a learning process: official documentation and tutorials, building a small hands-on project, practising regularly, asking mentors or communities, and gives an example of a technology learned this way.', '["documentation", "practice", "project", "hands on", "example", "community"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'learning', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Why should we hire you?', 'Connects the candidate''s skills, projects and qualities to the needs of the role, highlights what makes them different such as quick learning or a relevant project, and shows enthusiasm and commitment.', '["skills", "project", "role", "learn", "contribute", "value"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'motivation', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Where do you see yourself in five years?', 'Realistic career growth plan related to the field: becoming skilled in a specific area, taking more responsibility, continuous learning or certifications, and contributing to the organisation.', '["grow", "skills", "responsibility", "learn", "contribute", "role"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'goals', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'How would you explain a technical concept to someone who is not technical?', 'Uses simple language without jargon, a real-life analogy, focuses on why it matters to the listener, checks their understanding, and gives a short example of doing this.', '["simple", "analogy", "example", "avoid jargon", "understand"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'communication', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'How do you manage your time between studies, projects and other activities?', 'Explains planning tools such as a schedule, to-do list or calendar, prioritising by importance and deadlines, avoiding distractions, and an example of balancing multiple responsibilities.', '["schedule", "priority", "plan", "deadline", "balance", "example"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'time_management', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What would you do if you saw a teammate copying code or data without permission?', 'Shows integrity: speaks privately and respectfully with the teammate first, explains plagiarism, licence or data privacy risks, encourages fixing it or giving credit, and escalates to the mentor or faculty if it continues.', '["integrity", "talk", "plagiarism", "permission", "credit", "escalate"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'ethics', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What is PL/SQL and what are the sections of a PL/SQL block?', 'PL/SQL is Oracle''s procedural extension to SQL that adds variables, conditions, loops and error handling to SQL statements. A PL/SQL block has an optional DECLARE section for variables, constants and cursors, a mandatory BEGIN section containing the executable statements, an optional EXCEPTION section for handling errors, and it ends with END. A block without a name is called an anonymous block and is not stored in the database.', '["procedural", "declare", "begin", "exception", "end", "anonymous block"]'::jsonb, 'technical', 120, 'technical', 'BSC_DS', 1, 2, 'Advanced Database Management Systems', 'PL/SQL basics: anonymous blocks', 1, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What is a cursor in PL/SQL?', 'A cursor is a pointer to a private memory area, called the context area, that Oracle uses to process a SQL statement and hold the rows it returns. It lets PL/SQL process a query''s result set one row at a time. Implicit cursors are created automatically by Oracle for DML and SELECT INTO statements, while explicit cursors are declared by the programmer for queries that return multiple rows.', '["pointer", "context area", "result set", "one row at a time", "implicit", "explicit"]'::jsonb, 'technical', 120, 'technical', 'BSC_DS', 1, 2, 'Advanced Database Management Systems', 'Cursors: implicit, explicit and parameterized', 1, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What is the difference between a stored procedure and a function in PL/SQL?', 'Both are named PL/SQL blocks stored in the database. A function must return exactly one value using the RETURN statement, and it can be called from a SQL statement such as a SELECT, provided it has no side effects like DML. A procedure does not have to return a value; it can pass values back through OUT or IN OUT parameters, and it is called as a standalone statement or from another block, not inside a SELECT. Procedures are typically used to perform an action, functions to compute a value.', '["return", "one value", "out parameter", "select", "procedure", "function"]'::jsonb, 'technical', 120, 'technical', 'BSC_DS', 1, 2, 'Advanced Database Management Systems', 'Stored procedures and functions', 2, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What is the difference between an IF-ELSIF ladder and a CASE statement in PL/SQL?', 'An IF-ELSIF ladder checks a series of boolean conditions one after another and executes the first branch whose condition is true, with an optional ELSE. A CASE statement selects one branch based on the value of a single selector expression, or with a searched CASE, on a list of WHEN conditions. CASE is usually more readable when comparing one variable against many values. If no WHEN matches and there is no ELSE, a CASE statement raises the CASE_NOT_FOUND exception, whereas IF simply does nothing.', '["if-elsif", "case", "selector", "when", "else", "case_not_found"]'::jsonb, 'technical', 120, 'technical', 'BSC_DS', 1, 2, 'Advanced Database Management Systems', 'Conditional statements: if, elsif, case', 2, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Explain the basic LOOP, WHILE loop and numeric FOR loop in PL/SQL and when you would use each.', 'A basic LOOP runs repeatedly until an EXIT or EXIT WHEN condition is met inside the body, so it always runs at least once. A WHILE loop checks its condition before each iteration and runs only while the condition is true, so it may run zero times. A numeric FOR loop runs over a fixed integer range such as FOR i IN 1..10, and the loop counter is declared and incremented automatically. Use FOR when the number of iterations is known, WHILE when it depends on a condition, and basic LOOP when the exit test falls in the middle or end of the body.', '["loop", "exit when", "while", "for", "range", "counter"]'::jsonb, 'technical', 120, 'technical', 'BSC_DS', 1, 2, 'Advanced Database Management Systems', 'Control structures in PL/SQL: loops', 3, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'How do you handle the case where a SELECT INTO query in PL/SQL returns no row or more than one row?', 'SELECT INTO must return exactly one row. If it returns no row Oracle raises the predefined exception NO_DATA_FOUND, and if it returns more than one row it raises TOO_MANY_ROWS. You handle them in the EXCEPTION section with WHEN NO_DATA_FOUND THEN and WHEN TOO_MANY_ROWS THEN, for example by printing a message or assigning a default value. A WHEN OTHERS handler can catch any remaining errors, often logging SQLCODE and SQLERRM.', '["select into", "no_data_found", "too_many_rows", "exception section", "when others", "predefined"]'::jsonb, 'technical', 120, 'technical', 'BSC_DS', 1, 2, 'Advanced Database Management Systems', 'Exception handling: system-defined and user-defined exceptions', 3, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'An UPDATE statement modifies 50 rows of a table. How many times will a row-level trigger and a statement-level trigger on that table fire, and why?', 'A row-level trigger, declared with FOR EACH ROW, fires once for every affected row, so it fires 50 times. A statement-level trigger fires only once for the whole UPDATE statement, regardless of how many rows are affected, even zero. Row-level triggers can use the :OLD and :NEW pseudo-records to see each row''s values before and after the change, while statement-level triggers cannot. Statement-level triggers suit tasks like auditing that the statement ran, row-level triggers suit per-row validation or history.', '["for each row", "50 times", "once", "statement-level", ":old", ":new"]'::jsonb, 'technical', 120, 'technical', 'BSC_DS', 1, 2, 'Advanced Database Management Systems', 'Triggers: row-level, statement-level and instead-of triggers', 4, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Why would you use a parameterized cursor instead of a regular explicit cursor?', 'A parameterized cursor accepts parameters when it is opened, such as CURSOR c_emp(p_dept NUMBER) IS SELECT ... WHERE dept_id = p_dept. This lets the same cursor definition be reused with different values, for example opening it once for department 10 and again for department 20, instead of declaring a separate cursor for each case. It makes code shorter and more maintainable, and avoids relying on global variables inside the query. The parameter values are passed in OPEN or in a cursor FOR loop.', '["parameter", "reuse", "open", "different values", "same cursor", "maintainable"]'::jsonb, 'technical', 120, 'technical', 'BSC_DS', 1, 2, 'Advanced Database Management Systems', 'Cursors: implicit, explicit and parameterized', 4, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'A row-level trigger on the EMPLOYEES table runs a SELECT on EMPLOYEES itself and fails with ORA-04091 mutating table error. Why does this happen and how can you fix it?', 'A mutating table is one that is currently being modified by the DML statement that fired the trigger. Oracle does not allow a row-level trigger to query or modify that same table, because its data is in an inconsistent, half-changed state, so it raises ORA-04091. Fixes include using a statement-level trigger which runs after all rows are changed, using a compound trigger that collects row data in a collection and processes it in the AFTER STATEMENT section, or moving the logic into a stored procedure. Sometimes the check can be replaced by a constraint instead.', '["mutating table", "row-level", "same table", "statement-level", "compound trigger", "inconsistent"]'::jsonb, 'technical', 120, 'technical', 'BSC_DS', 1, 2, 'Advanced Database Management Systems', 'Triggers: row-level triggers', 5, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'A PL/SQL program fetches one million rows with a cursor loop one row at a time and is very slow. How would you improve its performance?', 'Row-by-row fetching causes a context switch between the PL/SQL engine and the SQL engine for every row, which is slow. You can use BULK COLLECT to fetch many rows into a collection in one go, ideally with a LIMIT clause such as 1000 rows per fetch to control memory usage. For the DML part, use FORALL to send all the inserts or updates in a single batch. If possible, replace the whole loop with a single set-based SQL statement, which is usually fastest.', '["context switch", "bulk collect", "limit", "forall", "collection", "set-based"]'::jsonb, 'technical', 120, 'technical', 'BSC_DS', 1, 2, 'Advanced Database Management Systems', 'Collections and composite data types', 5, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Your team is building a payroll module with many related procedures, functions and shared variables. Why would you organise it as a PL/SQL package, and what best practices would you follow?', 'A package groups related procedures, functions, types, cursors and variables into one named unit with a specification and a body. The specification is the public interface, while the body holds the implementation and private helpers, so callers are shielded from internal changes and the body can be recompiled without invalidating dependent code. Packages are loaded into memory once per session, which improves performance, and package variables can hold session-level state. Best practices include exposing only what is needed in the spec, using consistent exception handling and logging, avoiding too much global state, and using overloading for similar operations.', '["package", "specification", "body", "public", "private", "shielded", "recompile"]'::jsonb, 'technical', 120, 'technical', 'BSC_DS', 1, 2, 'Advanced Database Management Systems', 'PL/SQL packages for modular database applications', 6, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'In a banking application a fund-transfer procedure must reject transfers that exceed the account balance and must never leave money debited without being credited. How would you design its error handling?', 'Check the balance first and, if it is insufficient, raise a user-defined exception, declared in the declaration section or raised with RAISE_APPLICATION_ERROR with a custom error number between -20000 and -20999 and a clear message. Perform the debit and credit in one transaction so that both succeed or neither does. In the exception handler, ROLLBACK any partial changes, log the error details, and re-raise the error so the calling application knows the transfer failed. Avoid a bare WHEN OTHERS THEN NULL, because it silently hides errors.', '["user-defined exception", "raise_application_error", "transaction", "rollback", "one transaction", "log", "re-raise"]'::jsonb, 'technical', 120, 'technical', 'BSC_DS', 1, 2, 'Advanced Database Management Systems', 'Exception handling: user-defined exceptions', 6, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What is PL/SQL and what is the structure of a PL/SQL block?', 'PL/SQL is Oracle''s procedural extension of SQL that adds variables, conditions, loops and exception handling to SQL statements. A PL/SQL block has an optional DECLARE section for variables, cursors and constants, a mandatory BEGIN section containing executable statements, an optional EXCEPTION section for handling errors, and ends with END. A block without a name is called an anonymous block and is not stored in the database. Named blocks such as procedures and functions are stored in the database.', '["procedural extension", "oracle", "declare", "begin", "exception", "end", "anonymous block"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Database Programming', 'PL/SQL basics: variables, executable statements, anonymous blocks', 1, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What are the types of loops available in PL/SQL?', 'PL/SQL has three types of loops: the basic or simple LOOP, the WHILE loop and the FOR loop. A basic LOOP repeats its statements until an EXIT or EXIT WHEN condition is met, so it always runs at least once. A WHILE loop checks its condition before each iteration and runs as long as the condition is true. A numeric FOR loop runs a fixed number of times over a range, such as FOR i IN 1..10, with the counter declared automatically, and REVERSE counts downwards.', '["basic loop", "exit when", "while loop", "condition", "for loop", "range", "reverse"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Database Programming', 'Control structures: while, loop, for, GOTO', 1, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What is the difference between an implicit cursor and an explicit cursor?', 'An implicit cursor is created automatically by Oracle for every DML statement and for SELECT INTO statements that return a single row. Its attributes are accessed using SQL%ROWCOUNT, SQL%FOUND and SQL%NOTFOUND. An explicit cursor is declared by the programmer for a SELECT query that may return multiple rows. It must be opened, fetched row by row and closed, and gives the programmer control over processing each row.', '["implicit cursor", "automatically", "select into", "sql%rowcount", "explicit cursor", "multiple rows", "opened"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Database Programming', 'Cursors: implicit, explicit and parameterized', 2, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What is the difference between a stored procedure and a function in PL/SQL?', 'Both are named PL/SQL blocks stored in the database. A function must return exactly one value using the RETURN statement, while a procedure does not have to return a value but can pass values back through OUT parameters. A function can be called from a SQL statement such as SELECT, as long as it does not perform DML, whereas a procedure cannot be called from SQL and is invoked with EXECUTE or from another block. Functions are typically used for computations and procedures for performing actions.', '["stored", "function", "return", "procedure", "out parameters", "called from a sql statement", "execute"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Database Programming', 'Stored procedures and functions', 2, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'How do you create and use a sequence to generate primary key values in Oracle?', 'A sequence is a database object that generates unique numbers, created with a statement like CREATE SEQUENCE emp_seq START WITH 1 INCREMENT BY 1. To get the next value, we use emp_seq.NEXTVAL, for example in an INSERT statement to fill the primary key column. emp_seq.CURRVAL returns the current value in the session after NEXTVAL has been called. Options like CACHE improve performance, and sequence numbers may have gaps after rollbacks or restarts.', '["create sequence", "unique numbers", "start with", "increment by", "nextval", "currval", "gaps"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Database Programming', 'Sequences in PL/SQL', 3, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'How do you define and raise a user-defined exception in PL/SQL?', 'A user-defined exception is declared in the DECLARE section as a variable of type EXCEPTION, for example low_balance EXCEPTION. In the executable section, it is raised explicitly with the RAISE statement when a condition is met, such as when the balance is below the withdrawal amount. It is then handled in the EXCEPTION section using WHEN low_balance THEN followed by the handling code. Alternatively, RAISE_APPLICATION_ERROR can raise a custom error number between -20000 and -20999 with a message.', '["declare", "exception", "raise", "when", "then", "raise_application_error"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Database Programming', 'Exception handling: system-defined and user-defined', 3, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'An UPDATE statement modifies 50 rows of a table. How many times does a row-level trigger and a statement-level trigger fire, and why?', 'A row-level trigger, defined with FOR EACH ROW, fires once for every affected row, so it fires 50 times. A statement-level trigger fires only once for the whole UPDATE statement, regardless of how many rows are affected, even if no rows are affected. Row-level triggers can access the old and new values of each row through :OLD and :NEW, so they are used for row auditing or validation. Statement-level triggers are used for actions like logging that the statement occurred or checking security.', '["row-level", "for each row", "50 times", "statement-level", "once", "old and new values"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Database Programming', 'Triggers: row-level, statement-level and INSTEAD OF', 4, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Compare an IF-ELSIF ladder with a CASE statement in PL/SQL. When is CASE better?', 'Both choose one branch among several conditions and execute only the first matching branch. An IF-ELSIF ladder evaluates conditions in order and is flexible because each condition can test different variables or ranges. A simple CASE statement compares one expression against several values, which is cleaner and more readable when checking a single variable, such as mapping grade letters to remarks. A searched CASE allows conditions like an IF ladder, and CASE can also be used as an expression that returns a value, and a CASE statement without a matching branch or ELSE raises CASE_NOT_FOUND.', '["if-elsif", "first matching", "simple case", "one expression", "searched case", "readable", "case_not_found"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Database Programming', 'Conditional statements: IF, ELSIF ladder, CASE', 4, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'A PL/SQL block processes one million rows one at a time in a cursor loop and is very slow. How would you improve its performance?', 'Row-by-row processing causes a context switch between the PL/SQL engine and the SQL engine for every row, which is slow. I would use bulk processing: BULK COLLECT to fetch rows into a collection, such as a nested table or associative array, in batches using the LIMIT clause to control memory. Then FORALL performs the INSERT, UPDATE or DELETE for the whole collection in one context switch. If possible, replacing the loop with a single set-based SQL statement is even faster, and SAVE EXCEPTIONS can capture row errors in FORALL.', '["context switch", "bulk collect", "collection", "limit", "forall", "set-based", "save exceptions"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Database Programming', 'Collections and composite data types', 5, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'A row-level trigger on the EMP table queries the same EMP table and fails with a ''mutating table'' error. Why does this happen and how can it be solved?', 'The ORA-04091 mutating table error occurs when a row-level trigger tries to read or modify the same table that the triggering statement is changing, because the table is in an inconsistent, mid-change state. Oracle prevents this to avoid unpredictable results. One solution is a compound trigger, which collects needed row data in the row-level section and does the query in the AFTER STATEMENT section. Other options are using a statement-level trigger, moving the logic into a stored procedure, or rethinking the design.', '["mutating table", "ora-04091", "row-level trigger", "same table", "compound trigger", "statement-level", "after statement"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Database Programming', 'Triggers: row-level, statement-level and INSTEAD OF', 5, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'You are building a banking module with many related procedures and functions. Why would you organise them into a PL/SQL package and how?', 'A package groups related procedures, functions, variables, cursors and exceptions into one named unit with two parts: the specification, which declares the public interface, and the body, which contains the implementation and private items. This gives encapsulation, because callers only see the specification, and modularity, which makes the code easier to maintain. The whole package is loaded into memory on first call, which improves performance, and the body can be changed without invalidating dependent code if the specification stays the same. It also supports overloading, package-level state and grants execute permission on the package only, improving security.', '["specification", "body", "encapsulation", "public", "private", "performance", "overloading"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Database Programming', 'PL/SQL packages', 6, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'In a production funds-transfer procedure, how would you design error handling so that money is never lost and problems can be traced?', 'The debit and credit should be in a single transaction, committed only after both succeed, and on any error the handler must ROLLBACK so the database stays consistent. Specific system exceptions such as NO_DATA_FOUND and user-defined exceptions like insufficient_funds should be handled with clear messages. Errors should be logged with SQLCODE, SQLERRM and the backtrace into a log table using an autonomous transaction, so the log survives the rollback. Avoid swallowing errors with WHEN OTHERS THEN NULL; instead log and re-raise them so the caller knows the transfer failed.', '["single transaction", "rollback", "no_data_found", "user-defined", "sqlerrm", "autonomous transaction", "re-raise"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Database Programming', 'Exception handling: system-defined and user-defined', 6, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What is a servlet?', 'A servlet is a Java class that runs on a web server inside a servlet container, such as Tomcat, and handles client requests to generate dynamic web content. It usually extends HttpServlet and overrides methods like doGet and doPost to process HTTP requests and send HTTP responses. Servlets are mapped to URLs using web.xml or the @WebServlet annotation.', '["java class", "servlet container", "tomcat", "httpservlet", "doget", "dopost", "dynamic"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Java', 'Servlets: API, life cycle and annotations', 1, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What is JDBC?', 'JDBC, Java Database Connectivity, is a Java API that lets Java programs connect to relational databases and execute SQL statements. It provides interfaces such as DriverManager, Connection, Statement, PreparedStatement and ResultSet. A database-specific JDBC driver converts JDBC calls into the database''s own protocol, so the same Java code can work with MySQL, Oracle or others by changing the driver and URL.', '["java database connectivity", "api", "driver", "connection", "preparedstatement", "resultset"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Java', 'JDBC architecture and database access', 1, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What is the difference between RequestDispatcher forward and response sendRedirect?', 'RequestDispatcher forward passes the same request and response to another resource on the server, such as a servlet or JSP; it happens entirely on the server, the browser URL does not change, and request attributes are preserved. sendRedirect sends a response telling the browser to make a new request to a different URL, so the URL changes, a new request is created, and the old request attributes are lost. Redirect can go to external sites and is slower because it needs an extra round trip.', '["forward", "server side", "same request", "url does not change", "sendredirect", "new request", "browser"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Java', 'RequestDispatcher, cookies and session tracking', 2, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What are JSP implicit objects? Name a few.', 'JSP implicit objects are objects created automatically by the JSP container that can be used directly in a JSP page without declaring them. There are nine: request, response, out, session, application, config, pageContext, page and exception. For example, request gives access to form parameters, out writes output to the client, session stores user-specific data and application stores data shared by the whole web application. The exception object is available only in error pages.', '["created by container", "request", "response", "out", "session", "application"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Java', 'JSP: life cycle, elements and implicit objects', 2, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Explain the life cycle of a servlet.', 'The servlet container loads the servlet class and creates a single instance, either on the first request or at startup. It then calls init() once to initialise resources. For each client request, the container calls service(), usually on a new thread, which dispatches to doGet, doPost or other methods based on the HTTP method. When the servlet is removed or the server shuts down, destroy() is called once to release resources, after which the object is garbage collected.', '["loaded", "single instance", "init", "service", "doget", "destroy", "thread"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Java', 'Servlets: life cycle', 3, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'How do Expression Language and JSTL help in writing cleaner JSP pages? Give an example.', 'Expression Language, written as ${...}, gives a simple syntax to access data stored in request, session or application scopes, bean properties and parameters without Java code, for example ${user.name} or ${param.city}. JSTL, the JSP Standard Tag Library, provides tags for common tasks like loops, conditions, formatting and SQL, such as <c:forEach> to loop through a list and <c:if> for conditions. Together they remove scriptlets, so pages are easier to read and maintain and follow MVC by keeping business logic in servlets.', '["expression language", "no scriptlets", "scopes", "jstl", "c:foreach", "c:if", "mvc"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Java', 'Expression Language and JSTL', 3, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Why is PreparedStatement preferred over Statement in JDBC?', 'PreparedStatement uses a precompiled SQL query with question-mark placeholders, and values are set using methods like setString and setInt. Because the values are sent separately from the SQL, user input cannot change the query structure, which prevents SQL injection. The query can be compiled once and executed many times with different parameters, improving performance. It also handles data types and special characters properly, making code cleaner than concatenating strings into a Statement.', '["precompiled", "placeholders", "sql injection", "setstring", "performance", "reuse"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Java', 'JDBC: Statement vs PreparedStatement', 4, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Compare stateless, stateful and singleton session beans. Give a use case for each.', 'A stateless session bean keeps no client-specific state between method calls, so the container can pool instances and serve many clients, which is good for operations like currency conversion or tax calculation. A stateful session bean maintains conversational state for one client across multiple calls, like a shopping cart, and is tied to that client for the session. A singleton session bean has only one instance per application shared by all clients, useful for application-wide caching or configuration, and it needs concurrency control. Stateless beans scale best, while stateful beans use more memory.', '["stateless", "pooled", "stateful", "conversational state", "shopping cart", "singleton", "one instance"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Java', 'Enterprise JavaBeans: session beans', 4, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'A servlet stores the logged-in username in an instance variable, and users sometimes see other users'' names. What is the bug and how do you fix it?', 'The container creates only one instance of a servlet and handles concurrent requests on multiple threads using that same instance. Instance variables are therefore shared by all requests, so one request can overwrite the username while another is still using it, a race condition. The fix is to use local variables inside doGet or doPost, which are thread-safe because each thread has its own stack, and store user-specific data in the HttpSession or request attributes. Synchronization should be avoided as a fix because it hurts performance.', '["one instance", "multiple threads", "instance variable", "race condition", "local variables", "httpsession"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Java', 'Servlets: thread safety', 5, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'A JPA application loads a list of 100 orders and then accesses each order''s customer, generating 101 SQL queries. What is this problem and how do you fix it?', 'This is the N plus 1 select problem. One query loads the orders, and then, because the customer relationship is lazily loaded, a separate query runs for each order''s customer when it is accessed. It causes heavy database load and slow pages. The fix is to fetch the related data in one query, using a JPQL JOIN FETCH, an entity graph, or batch fetching. Making everything eager loading is not a good general fix, because it can load far more data than needed in other cases.', '["n plus 1", "lazy loading", "separate query", "join fetch", "entity graph", "eager loading"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Java', 'Persistence, object/relational mapping and JPA', 5, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Your Java web application opens a new JDBC connection for every request and becomes very slow under load. How would you redesign database access for production?', 'Opening a database connection is expensive, involving network setup and authentication, so creating one per request wastes time and can exhaust the database''s connection limit. I would use a connection pool, configured as a DataSource in the application server and looked up through JNDI, or a library like HikariCP, so connections are reused. The pool size, timeouts and validation should be tuned to the expected load. Code must always return connections to the pool by closing them in try-with-resources, and queries should use PreparedStatement and transactions properly.', '["expensive", "connection pool", "datasource", "jndi", "try-with-resources", "pool size"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Java', 'JDBC architecture; Interceptors and JNDI', 6, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'In an e-commerce system, sending order confirmation emails and updating inventory makes checkout slow. How could message-driven beans help, and what trade-offs should you consider?', 'The checkout can place an order message on a JMS queue and return to the user immediately. A message-driven bean listens on that queue and processes messages asynchronously, sending emails and updating inventory in the background, so the user does not wait. The container manages a pool of MDB instances for concurrency, and the queue absorbs load spikes and decouples the components. Trade-offs include eventual consistency, so inventory may update a little later, the need to handle failures with retries and dead-letter queues, preventing duplicate processing, and more complex monitoring.', '["jms queue", "message-driven bean", "asynchronous", "decoupling", "eventual consistency", "retries"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 5, 'Advanced Java', 'Enterprise JavaBeans: message-driven beans', 6, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What is a list comprehension in Python?', 'A list comprehension is a concise way to create a new list from an iterable in a single expression. Its syntax is square brackets containing an expression, a for clause and an optional if condition, for example [x * x for x in range(10) if x % 2 == 0] gives the squares of even numbers. It is more readable and usually faster than building the list with a for loop and append. Python also supports dictionary and set comprehensions using curly braces.', '["concise", "new list", "iterable", "for clause", "if condition", "square brackets"]'::jsonb, 'technical', 120, 'technical', 'BSC_AI', 2, 3, 'Advanced Python Programming', 'List, dictionary and set comprehensions', 1, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What is a lambda function in Python?', 'A lambda function is a small anonymous function defined with the lambda keyword. It can take any number of arguments but contains only a single expression, whose value is returned automatically. For example, lambda x: x * 2 doubles its input. Lambdas are commonly used as short arguments to functions like map, filter, sorted and reduce.', '["anonymous", "lambda keyword", "single expression", "arguments", "returned", "map"]'::jsonb, 'technical', 120, 'technical', 'BSC_AI', 2, 3, 'Advanced Python Programming', 'Lambda expressions', 1, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What is the difference between an iterator and a generator in Python?', 'An iterator is any object that implements the __iter__ and __next__ methods, returning items one at a time and raising StopIteration when finished. A generator is a simple way to create an iterator using a function with the yield keyword, or a generator expression. Each time next is called, the generator resumes from where it paused and remembers its state. So every generator is an iterator, but generators need much less code than writing an iterator class by hand.', '["iter method", "next method", "stopiteration", "yield", "state", "every generator is an iterator"]'::jsonb, 'technical', 120, 'technical', 'BSC_AI', 2, 3, 'Advanced Python Programming', 'Iterators and generators', 2, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What is the difference between method overloading and method overriding in Python?', 'Method overriding is when a subclass defines a method with the same name as a method in its parent class, replacing the parent''s behaviour; super() can still call the parent version. Method overloading means having multiple methods with the same name but different parameters. Python does not support traditional overloading, since a later definition replaces the earlier one, so it is simulated using default arguments, *args and **kwargs, or functools.singledispatch. Operator overloading is done using magic methods like __add__.', '["overriding", "subclass", "same name", "overloading", "default arguments", "variable arguments"]'::jsonb, 'technical', 120, 'technical', 'BSC_AI', 2, 3, 'Advanced Python Programming', 'Method overloading and overriding', 2, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'How does a decorator work in Python? Explain with a timing decorator example.', 'A decorator is a function that takes another function as an argument and returns a new function that adds behaviour before or after calling the original, without changing its code. For a timing decorator, the inner wrapper function records the start time, calls the original function with *args and **kwargs, records the end time, prints the difference and returns the result. Writing @timer above a function definition is the same as func = timer(func). The wrapper is a closure because it remembers the original function from the enclosing scope, and functools.wraps is used to keep the original name and docstring.', '["function as argument", "wrapper", "closure", "returns new function", "functools.wraps"]'::jsonb, 'technical', 120, 'technical', 'BSC_AI', 2, 3, 'Advanced Python Programming', 'Decorators and closures', 3, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What is a context manager, and what happens when you use ''with open(...) as f'' in Python?', 'A context manager is an object that sets up and cleans up a resource automatically, by implementing __enter__ and __exit__ methods. In ''with open(file) as f'', the file is opened and __enter__ returns the file object assigned to f. When the block ends, whether normally or because of an exception, __exit__ is called and the file is closed automatically. This prevents resource leaks; custom context managers can also be made with contextlib.contextmanager.', '["enter method", "exit method", "automatically closed", "exception", "resource", "contextlib"]'::jsonb, 'technical', 120, 'technical', 'BSC_AI', 2, 3, 'Advanced Python Programming', 'Advanced file handling: context managers', 3, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Class D inherits from B and C, and both B and C inherit from A and override a method show(). If you call D().show(), which version runs and why?', 'B''s version of show() runs. Python uses the Method Resolution Order, computed with the C3 linearization algorithm, to decide where to look for methods. For class D(B, C), the MRO is D, B, C, A, object, so Python searches D first, then B, finds show() there and calls it. You can check this with D.__mro__ or D.mro(). If B''s show() calls super().show(), the next class in the MRO, C, is called, not A directly, which solves the diamond problem.', '["method resolution order", "c3 linearization", "searches b before c", "b''s version", "super", "diamond problem"]'::jsonb, 'technical', 120, 'technical', 'BSC_AI', 2, 3, 'Advanced Python Programming', 'Multiple inheritance and MRO', 4, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Why does multithreading not speed up a CPU-heavy Python program, and what would you use instead?', 'In standard CPython, the Global Interpreter Lock allows only one thread to execute Python bytecode at a time. So for CPU-bound work, threads take turns rather than running in parallel, and there is little or no speedup. Multiprocessing creates separate processes, each with its own interpreter and GIL, so they can run truly in parallel on multiple CPU cores. Threads and async/await are still useful for I/O-bound tasks like network or file operations, where the GIL is released while waiting.', '["global interpreter lock", "one thread", "cpu-bound", "multiprocessing", "multiple cores", "i/o-bound"]'::jsonb, 'technical', 120, 'technical', 'BSC_AI', 2, 3, 'Advanced Python Programming', 'Multithreading, multiprocessing and async/await', 4, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'You implement a Singleton database-connection class in Python. What problems can occur in a multithreaded program, and how would you make it safe?', 'A Singleton ensures only one instance of a class exists, usually by checking a class variable in __new__ and creating the instance if it is None. In a multithreaded program, two threads may check at the same moment, both see None and create two instances, which is a race condition. The fix is to protect creation with a threading.Lock, often using double-checked locking so the lock is only taken when the instance is missing. Alternatively, a module-level instance works because modules are imported once, and you should also consider that one shared connection may itself not be thread-safe, so a connection pool may be better.', '["single instance", "__new__", "race condition", "threading.lock", "double-checked locking", "connection pool"]'::jsonb, 'technical', 120, 'technical', 'BSC_AI', 2, 3, 'Advanced Python Programming', 'Design patterns: Singleton', 5, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'A production script uses print statements and a bare except that hides all errors. How would you improve its error handling with custom exceptions and logging?', 'A bare except catches everything, including KeyboardInterrupt and real bugs, and hides the cause, so we should catch only specific exceptions. Define custom exceptions by subclassing Exception, such as InvalidRecordError, and raise them with clear messages so callers can handle each case differently. Replace print with the logging module, using levels such as DEBUG, INFO, WARNING, ERROR and CRITICAL, and write logs to a file with timestamps. Use logger.exception inside except blocks to record the full traceback, and use finally or context managers for cleanup.', '["bare except", "specific exceptions", "subclass exception", "logging module", "levels", "traceback"]'::jsonb, 'technical', 120, 'technical', 'BSC_AI', 2, 3, 'Advanced Python Programming', 'Custom exceptions, logging and debugging', 5, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Your ML project works on your laptop but fails on a teammate''s machine with version errors. How would you manage environments and dependencies to fix this?', 'Each project should use its own virtual environment, created with venv or conda, so its packages do not clash with system or other project packages. Dependencies should be recorded with pinned versions in a requirements.txt using pip freeze, or in a pyproject.toml with a lock file using tools like Poetry or uv. Teammates then create a fresh virtual environment and install from that file to get identical versions. The Python version itself should also be documented, and for full reproducibility Docker can be used. The virtual environment folder should not be committed to Git, only the dependency files.', '["virtual environment", "venv", "requirements.txt", "pinned versions", "pip freeze", "lock file"]'::jsonb, 'technical', 120, 'technical', 'BSC_AI', 2, 3, 'Advanced Python Programming', 'Modules, packages, virtual environments and dependency management', 6, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'You are building a Python app that inserts user-entered data into MySQL. A reviewer says your code, which builds SQL with string formatting, is unsafe. Explain the issue and the best practices you would follow.', 'Building SQL by inserting user input with string formatting allows SQL injection, where malicious input changes the query, for example to delete tables or read other users'' data. The fix is to use parameterized queries with placeholders, such as cursor.execute with %s for MySQL or ? for SQLite and passing values separately, so the driver escapes them safely. Other best practices are committing transactions after changes and rolling back on errors, closing cursors and connections using context managers, using connection pooling, and storing credentials in environment variables rather than code.', '["sql injection", "parameterized queries", "placeholders", "commit", "rollback", "close connection"]'::jsonb, 'technical', 120, 'technical', 'BSC_AI', 2, 3, 'Advanced Python Programming', 'Database connectivity (SQLite/MySQL) and CRUD operations', 6, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What is the Software Development Life Cycle? Name its main phases.', 'The Software Development Life Cycle, or SDLC, is a structured process for planning, building, testing and maintaining software so that it meets requirements with good quality, on time and within budget. Its main phases are requirement gathering and analysis, design, implementation or coding, testing, deployment and maintenance. Different SDLC models such as Waterfall, V-model, Agile and DevOps organize these phases differently, for example sequentially in Waterfall and in short iterations in Agile.', '["structured process", "requirements", "design", "coding", "testing", "deployment", "maintenance"]'::jsonb, 'technical', 120, 'technical', 'BCA', 3, 6, 'AI-Driven Software Development', 'SDLC models (Waterfall, Agile, DevOps, V-model)', 1, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What is an AI pair programming tool? Give examples.', 'An AI pair programming tool is an assistant integrated into the code editor or IDE that uses large language models trained on code to suggest code completions, whole functions, tests and explanations as the developer types or describes intent in natural language. It acts like a partner programmer that speeds up routine coding. Examples are GitHub Copilot, Amazon CodeWhisperer, now part of Amazon Q Developer, and similar assistants. The developer remains responsible for reviewing and accepting the suggestions.', '["ide", "large language models", "suggest", "code completion", "github copilot", "codewhisperer", "review"]'::jsonb, 'technical', 120, 'technical', 'BCA', 3, 6, 'AI-Driven Software Development', 'AI pair programming tools: GitHub Copilot, Amazon CodeWhisperer', 1, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What are the main benefits and limitations of using AI in software development?', 'AI can automate repetitive tasks like boilerplate code, test generation and documentation, speed up development, help find bugs early and analyze logs and requirements at scale. It also helps beginners learn and improves productivity. Its limitations are that AI can produce incorrect or insecure code, called hallucinations, lacks full understanding of business context, may reproduce licensed or biased content, and depends on the quality of its training data. Over-reliance can reduce developer skills, so human review remains essential.', '["automate", "productivity", "bugs", "incorrect", "hallucinations", "insecure", "human review"]'::jsonb, 'technical', 120, 'technical', 'BCA', 3, 6, 'AI-Driven Software Development', 'Benefits and limitations of AI in the SDLC', 2, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'How can natural language processing help in requirements engineering?', 'Requirements are mostly written in natural language in documents, emails and user feedback. NLP can extract requirements from these texts, classify them into functional and non-functional requirements, and detect ambiguous words such as fast or user-friendly. It can find duplicate or conflicting requirements using text similarity and help prioritize them, for example using sentiment or frequency in user reviews. This saves analyst time and improves the clarity and completeness of the requirements specification.', '["natural language", "extract", "classify", "functional", "non-functional", "ambiguous", "duplicate", "prioritize"]'::jsonb, 'technical', 120, 'technical', 'BCA', 3, 6, 'AI-Driven Software Development', 'NLP for requirements gathering, classification and prioritization', 2, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'How does predictive test selection work, and why is it useful in a large project?', 'In large projects, running the full test suite on every code change takes too long. Predictive test selection uses a machine learning model trained on historical data such as which files changed, past test results and test-to-code dependencies to predict which tests are most likely to fail for a new change. Only those high-risk tests are run first or run on each commit, while the full suite runs less often, such as nightly. This reduces CI time and cost and gives faster feedback, while still catching most failures.', '["full test suite", "machine learning", "historical", "changed files", "likely to fail", "faster feedback", "ci"]'::jsonb, 'technical', 120, 'technical', 'BCA', 3, 6, 'AI-Driven Software Development', 'Automated test case generation and predictive test selection', 3, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'How do LLM-based code completion tools generate code from a developer''s prompt or comment?', 'A large language model is trained on huge amounts of source code and text to predict the next token given previous tokens. The tool sends context, such as the developer''s comment, the current file, nearby code and sometimes related files, as a prompt to the model. The model then generates the most probable continuation token by token, producing code that matches the described intent. Good prompts with clear comments, function names and examples improve results. The generated code is probabilistic, so it must be reviewed and tested.', '["large language model", "trained", "next token", "context", "prompt", "probabilistic", "reviewed"]'::jsonb, 'technical', 120, 'technical', 'BCA', 3, 6, 'AI-Driven Software Development', 'LLM-based code synthesis and intelligent code completion', 3, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Compare traditional static analysis tools with machine learning based bug and code smell detection.', 'Traditional static analysis tools, like linters, use hand-written rules and patterns to detect issues, so they are precise and explainable for known problems but miss issues not covered by rules. ML-based detection learns from historical code, past bugs and fixes and code metrics such as complexity and churn, so it can find subtle patterns and predict bug-prone files or code smells like god classes or long methods. However, ML models can give false positives, need good labelled data and are harder to explain. In practice both are combined.', '["static analysis", "rules", "explainable", "historical", "code metrics", "code smells", "false positives"]'::jsonb, 'technical', 120, 'technical', 'BCA', 3, 6, 'AI-Driven Software Development', 'ML-based bug detection and code smell prediction', 4, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What is AIOps, and why is ML-based log anomaly detection better than fixed threshold alerts?', 'AIOps means using artificial intelligence and machine learning for IT operations, such as monitoring, event correlation, anomaly detection and root cause analysis. Fixed threshold alerts, like CPU above 90 percent, cannot adapt to normal patterns such as daily traffic peaks, so they generate false alarms or miss unusual behaviour below the threshold. ML models learn the normal baseline of logs and metrics, including seasonality, and flag deviations or unusual log patterns. They can also correlate related alerts to reduce alert fatigue and speed up incident resolution.', '["artificial intelligence", "it operations", "threshold", "false alarms", "baseline", "anomaly", "alert fatigue", "root cause"]'::jsonb, 'technical', 120, 'technical', 'BCA', 3, 6, 'AI-Driven Software Development', 'AI in CI/CD, log anomaly detection and AIOps', 4, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'An AI tool suggests a large refactoring of a legacy module. How would you safely apply it?', 'I would first make sure the module has good automated tests, adding characterization tests if needed, so behaviour can be verified before and after the change. I would review the AI''s suggestion carefully, understand each change, and apply it in small incremental steps rather than one big change. After each step I would run the tests, static analysis and security scans, and compare performance. The changes would go through normal code review and version control, so they can be rolled back if problems appear in staging or production.', '["automated tests", "review", "small incremental steps", "run the tests", "static analysis", "code review", "rollback"]'::jsonb, 'technical', 120, 'technical', 'BCA', 3, 6, 'AI-Driven Software Development', 'AI for refactoring, bug prediction and documentation', 5, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'An AI assistant recommends moving your small team''s monolithic application to microservices. How would you evaluate this recommendation?', 'I would treat the recommendation as an input, not a decision, and check it against our actual requirements, such as scalability needs, team size, deployment frequency and domain complexity. Microservices give independent scaling and deployment, but add complexity in networking, monitoring, data consistency and DevOps, which may not suit a small team. I would ask the AI to explain its reasoning and trade-offs, verify claims with documentation and benchmarks, and possibly start with a modular monolith or extract one service as a pilot. The final decision should be documented in an architecture decision record.', '["requirements", "team size", "trade-offs", "complexity", "independent scaling", "modular monolith", "pilot"]'::jsonb, 'technical', 120, 'technical', 'BCA', 3, 6, 'AI-Driven Software Development', 'AI-assisted architecture decisions and design recommendation', 5, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Your company wants developers to use AI coding assistants on a proprietary codebase. What security, legal and ethical policies would you recommend?', 'For security, use enterprise versions that do not retain or train on company code, and never paste secrets, passwords or customer data into prompts. AI-generated code should pass the same code review, testing and security scanning, such as SAST and dependency checks, since it may contain vulnerabilities. Legally, enable filters that block suggestions matching public code and check licence compliance to avoid copyright issues. Ethically, developers remain accountable for the code, AI use should be transparent, and any AI-driven decisions affecting users should be explainable and tested for bias.', '["data retention", "secrets", "code review", "security scanning", "licence", "copyright", "accountable", "bias"]'::jsonb, 'technical', 120, 'technical', 'BCA', 3, 6, 'AI-Driven Software Development', 'Explainable AI, fairness, security and legal issues', 6, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Your team plans to rely on AI-generated unit tests to increase test coverage from 40% to 80% quickly. What risks do you see and how would you ensure the tests are valuable?', 'The main risk is that AI-generated tests may only check what the current code does, including its bugs, or have weak assertions, so coverage increases without really catching defects. They may also be flaky, duplicate each other or be hard to maintain. To ensure value, developers should review tests against the requirements, focus on important logic and edge cases, and use mutation testing to check that tests fail when the code is deliberately changed. Coverage should be treated as a guide, not the goal, and tests must run reliably in the CI pipeline.', '["weak assertions", "existing bugs", "flaky", "review", "edge cases", "mutation testing", "coverage"]'::jsonb, 'technical', 120, 'technical', 'BCA', 3, 6, 'AI-Driven Software Development', 'Automated test case generation', 6, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What is the Software Development Life Cycle? Name its main phases.', 'The Software Development Life Cycle, or SDLC, is a structured process for planning, building, testing and maintaining software so that it meets requirements with good quality, on time and within budget. Its main phases are requirement gathering and analysis, design, implementation or coding, testing, deployment and maintenance. Different SDLC models such as Waterfall, V-model, Agile and DevOps organize these phases differently, for example sequentially in Waterfall and in short iterations in Agile.', '["structured process", "requirements", "design", "coding", "testing", "deployment", "maintenance"]'::jsonb, 'technical', 120, 'technical', 'BSC_IT', 3, 6, 'AI-Driven Software Development', 'SDLC models (Waterfall, Agile, DevOps, V-model)', 1, 'bank');
